<script setup lang="ts">
import{ref,onMounted}from'vue';import{v1}from'../api';import{DEFAULT_AGENT_SETTINGS,DEFAULT_SUBAGENT_SETTINGS,type AgentRuntimeSettings}from'../../contracts/models';
const all=ref<AgentRuntimeSettings>({...DEFAULT_AGENT_SETTINGS}),draft=ref({...DEFAULT_SUBAGENT_SETTINGS}),busy=ref(false),error=ref(''),notice=ref('');
onMounted(async()=>{try{all.value=await v1('/api/v1/agent-settings');draft.value={...DEFAULT_SUBAGENT_SETTINGS,...all.value.subagent};}catch(e){error.value=String(e);}});
async function save(){busy.value=true;try{all.value=await v1('/api/v1/agent-settings',{method:'PUT',body:JSON.stringify({...all.value,subagent:draft.value})});notice.value='已保存，新任务使用这些设置。';error.value='';}catch(e){error.value=String(e);}finally{busy.value=false;}}
</script>
<template><section aria-label="子代理设置"><p class="settings-description">主 Agent 可以派出独立研究会话。子代理仅使用读取、检索和任务清单工具，深度为一层，用量计入当前任务。</p><form @submit.prevent="save"><div class="settings-group"><label class="setting-row"><span>允许派出子代理</span><input v-model="draft.enabled" type="checkbox"></label><label class="setting-row"><span>每次最多工具步骤</span><input v-model.number="draft.maxSteps" aria-label="子代理最多步骤" type="number" min="1" max="50" required></label><label class="setting-row"><span>超时秒数</span><input v-model.number="draft.timeoutSeconds" aria-label="子代理超时秒数" type="number" min="10" max="600" required></label></div><button class="btn" :disabled="busy" type="submit">保存子代理设置</button></form><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p></section></template>
<style scoped>input[type=number]{width:100px;background:var(--bg-input);color:var(--fg);border:1px solid var(--border);border-radius:6px;padding:6px}button{margin-top:16px}[role=alert]{color:var(--danger)}</style>
